"""Metadata/docs/evidence only; verify source/dependency identity after smoke."""
from signalpost.portable_paths import portable, portable_text  # saved paths stay repo-relative
import hashlib,importlib.metadata,json,subprocess,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[3]
DEST=ROOT/'reports/r5/release-v4b'

def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def load(p):return json.loads(p.read_text(encoding='utf8'))

def version():
    p=ROOT/'pyproject.toml';s=p.read_text(encoding='utf8');assert 'version = "1.2.0"' in s
    p.write_text(portable_text(s.replace('version = "1.2.0"','version = "1.3.0"',1)),encoding='utf8')
    # Only the editable project version changes; all third-party pins remain.
    p=ROOT/'uv.lock';s=p.read_text(encoding='utf8');old='name = "signalpost-agent"\nversion = "1.2.0"';assert old in s
    p.write_text(portable_text(s.replace(old,'name = "signalpost-agent"\nversion = "1.3.0"',1)),encoding='utf8')
    print('Metadata updated to 1.3.0; run uv sync --frozen, final pytest, then report')

def report():
    meta=load(DEST/'clean_clone.json');daily=load(DEST/'daily-summary.json');edge=load(DEST/'edge-summary.json')
    installed=load(DEST/'installation-final.json');original=load(DEST/'installation-smoke.json')
    assert installed['installed_version']=='1.3.0'
    assert load(DEST/'pytest.json')['exit_code']==load(DEST/'pytest-version.json')['exit_code']==0
    manifest=load(DEST/'source_manifest.json');assert all(sha(ROOT/name)==digest for name,digest in manifest.items())
    a={d['name']:d['version'] for d in original['dependencies'] if d['name']!='signalpost-agent'}
    b={d['name']:d['version'] for d in installed['dependencies'] if d['name']!='signalpost-agent'}
    assert a==b,'Third-party dependency versions changed'
    assert daily['terminal_envelopes']==100 and edge['terminal_envelopes']==10
    assert daily['verification']['complete_briefing_contracts']==100
    prior={sample:load(ROOT/'reports/r5/stageC'/sample/'counts.json')['metrics'] for sample in ('frozen','daily')}
    fm=load(ROOT/'reports/r5/stageC/financial_metrics.json')
    table='| Metric | Frozen 20261017 (C) | Seed 20261113 (C) | New mock 20261114 |\n|---|---:|---:|---:|\n'
    for label,key,mock in [('Websites','verified_websites','websites'),('Social companies','social_profile_companies','social_companies'),('Job companies','job_ad_companies','job_companies'),('Contacts','contacts','contacts'),('Activity claims','activity_claims','activity_claims'),('Facts','total_facts','facts'),('HTTP','http_requests','http_requests'),('Wall seconds','process_wall_seconds','wall_seconds')]:
        vals=[prior[s][key] for s in ('frozen','daily')]+[daily[mock]]
        table+='| '+label+' | '+' | '.join(f'{v:.3f}' if isinstance(v,float) else str(v) for v in vals)+' |\n'
    for label,key in [('Derived ratios','derived_ratios'),('YoY metrics','yoy_metrics')]:
        mock=(daily['formulas'].get('operating_margin',0)+daily['formulas'].get('equity_ratio',0)) if key=='derived_ratios' else daily['formulas'].get('revenue_yoy',0)
        table+='| '+label+' | '+str(fm['frozen'][key])+' | '+str(fm['daily'][key])+' | '+str(mock)+' |\n'
    p=ROOT/'README.md';s=p.read_text(encoding='utf8');start=s.index('## Revision 5 / v1.2.0');end=s.index('Historical revision 3b',start)
    section='''## Revision 5 / v1.3.0

- The official seven evaluator flags enable website discovery, hiring and public website activity; a searchable profile site is generated by default.
- Five-part cited briefings explain activity, changes/first-run context, unknowns, financial context and a supported takeaway. Derived ratios and comparable-period YoY cite both inputs; matching units cancel without inventing absolute scale.
- Registry activity includes the complete returned company/proven-subunit event timeline within 36 months and a 50-event cap. Accounts retain earlier returned entity periods and evidence-linked available-copy years.
- The fresh bundled official NAV index is discovery only; published jobs require current exact employer/proven-subunit proof. Owned careers links use strict current-posting checks.
- Website fixes preserve one DNS nomination per www/non-www pair, source-first candidate order, veto/cache reuse, bounded proof-only sitemap discovery and honest challenge blocking. Default 8/13 ceilings, the existing adaptive allowance and shared 1,850 HTTP / 35-minute limits per 100 unique inputs remain enforced. Sitemaps never supply news.

Measured results below are observational source checks, not an official score or causal recall comparison. All three runs use exactly the seven flags and fresh state; provider cost is $0. The new seed-20261114 mock is disjoint from both earlier samples.

'''+table+'''
[v1.3.0 clean-clone release evidence, commands, URL/job hand checks and limitations](reports/r5/release-v4b/RELEASE_REPORT.md). The release is local; nothing is published or pushed. [Historical v1.2.0 check](reports/r5/release-v4/RELEASE_REPORT.md).

'''
    p.write_text(portable_text(s[:start]+section+s[end:]),encoding='utf8')
    source_tree=subprocess.check_output(['git','rev-parse',meta['tested_source_commit']+':src'],cwd=ROOT,text=True).strip()
    text='# Release v4b - Revision 5 / v1.3.0\n\nPASS for the requested technical release checks. No new application features, push or publication. Author/committer: Nethra Venkat <nethravenkat510@gmail.com>. The local annotated v1.3.0 tag identifies the release commit; its annotation records that commit SHA. The report names the exact tested source commit below; a commit cannot embed its own final hash.\n\n'
    text+='## Clean clone and tested source\n\nExact tested revision/r5 HEAD: `'+meta['tested_source_commit']+'`; source tree `'+source_tree+'`. Clone: `'+meta['clone_directory']+'`. It was created with git clone --no-hardlinks --single-branch --branch revision/r5 from the local repository into a new temporary workspace directory. It began with no tracked changes or copied runtime state. uv sync --frozen installed an isolated .venv; installation-smoke.json records interpreter/prefix/module/version and dependency licences, proving the clone was loaded. Initial full pytest and every sample/extraction/smoke/verification command run from this clone. No external application code was copied.\n\n'
    text+='The new 100-company smoke tested metadata version 1.2.0; the accepted exact-prior-input edge rerun tested version 1.3.0. Between them, only pyproject/uv.lock editable project metadata and README/evidence changed to 1.3.0. A second uv sync --frozen and full pytest passed; all application source bytes and third-party dependency versions remain unchanged. installation-final.json and release_checks.json verify this identity. No lock upgrade or source behavior change is hidden in the release.\n\n'
    initial_test=load(DEST/'pytest.json');final_test=load(DEST/'pytest-version.json')
    text+='Full unchanged pytest: 912 passed before the metadata bump ('+f"{initial_test['wall_seconds']:.3f}"+' seconds wrapper wall) and 912 passed after ('+f"{final_test['wall_seconds']:.3f}"+' seconds wrapper wall). The first environmental trial incorrectly applied the live-smoke search-disable override to tests that expect a fake provider; its two failures are preserved as pytest-environment-trial.*. Removing that override only for pytest restored the existing test contract; no application/test assertion changed. Both live smokes kept search disabled and cost $0. The final environment omits real Brave credentials for tests; the search cases inject synthetic credentials and a fake provider.\n\n'
    text+='## New disjoint sample\n\nHash-checked existing official snapshots, not a newly downloaded universe. Uniform random.Random(20261114).sample of the original corpus order after excluding both prior 100-company cohorts. Universe 411160; excluded 200; eligible 410960. Sample is 100 unique valid identifiers, zero overlap with seeds 20261017 and 20261113; all 100 bulk rows extracted.\n\n'
    for label,value in [('Universe archive SHA-256',meta['universe']['sha256']),('Universe content SHA-256',meta['universe_content_sha256']),('Registry snapshot SHA-256',meta['registry_snapshot']['sha256']),('Sample SHA-256',meta['sample_sha256']),('Bulk subset SHA-256',meta['subset_sha256'])]:text+='- '+label+': `'+value+'`\n'
    text+='\n## Smoke results\n\nBoth commands use exactly the seven evaluator flags, default enrichment/site/caps, independent fresh working directories and default state/. Search is disabled through the recorded environment, template synthesis is default and no model/API key is needed. No cap, feature, state, time or synthesis flag is added.\n\n| Check | New 100 | Edge 10 rows |\n|---|---:|---:|\n'
    for label,key in [('Ordered terminal envelopes','terminal_envelopes'),('Unique input IDs','unique_inputs'),('Duplicates','duplicates'),('Exit','exit_code'),('HTTP','http_requests'),('HTTP ceiling','http_cap'),('Wall seconds','wall_seconds'),('Websites','websites'),('Owned social URLs','social_urls'),('Jobs','jobs'),('Facts','facts'),('Provider cost USD','total_cost_usd')]:
        text+='| '+label+' | '+' | '.join(f'{d[key]:.3f}' if isinstance(d[key],float) else str(d[key]) for d in (daily,edge))+' |\n'
    text+='\nThe 100-company smoke is well below 45 minutes, <=1850 HTTP, within the effective/requested deadline, exit 0, site generated. verify_output.py validates hashed source receipts, supported values, financial arithmetic, filing years, registry events, current exact-employer jobs and all five cited briefing topics. Unsupported synthesis/briefing values: zero. Every envelope mirrors run.synthesis/profile.synthesis; all 100 daily and 10 edge contracts have activity/change/unknown/financial/takeaway topics. The accepted edge batch is byte-identical to the previous release-v4 ten-row input and uses its hash-checked bulk subset, with a fresh edge-repeat state. It preserves two invalid checksums and one duplicate at their input positions, emits ten terminal rows, performs no requests for invalid orgs and has identical duplicate envelopes. Invalid checksum profiles remain explicitly failed placeholders. An earlier same-pattern edge trial using seven companies from the new cohort is retained under trials/new_cohort_edge; it is not substituted for the exact prior-input rerun.\n\n'
    text+='## Exact run commands\n\nFrom the working directories in daily.json/edge.json, using recorded environment overrides:\n\n'
    for kind in ('daily','edge'):
        run=load(DEST/(kind+'.json'));text+='### '+kind+'\n\nWorking directory: `'+run['cwd']+'`\n\n```powershell\n'+(DEST/(kind+'-run.ps1')).read_text(encoding='utf8').strip()+'\n```\n\n'
    text+='## Prior samples and new mock\n\n'+table+'\nThese are different cohorts and live retrieval times. Counts do not imply exhaustive real-world coverage; exit zero does not mean every source succeeded. Section states/failure codes remain explicit in daily-summary.json and the complete report. No previous proof is reused to improve the mock. Ratios/YoY are dimensionless supported arithmetic, not forecasts. Absolute unit/scale is never inferred.\n\n'
    text+='## Hand checks, APIs, licences and cost\n\nurls.md/urls.json list every mock published website, social URL and job with company/org number, tier and exact saved excerpts, publisher URL, retrieval date, hash and locator. Registry homepage/social assertions are separately marked and are not ownership-verified sites. Review weaker HIGH proof separately from exact VERIFIED proof. Jobs include title/publication/deadline and exact employer/proven-subunit evidence. No contact-person text or job descriptions are republished by the inventory.\n\n'
    text+='APIs: official Brreg Enhetsregisteret company/roles/subunits and shared 36-month update calls; official Regnskapsregisteret figures and annual-accounts available-copy years; official NAV feed/detail/public-token service and bundled discovery index; bounded public company-owned HTML/linked feeds/careers and proof-only maps. Robots/terms, SSRF/public-IP pinning/TLS, vetoes, politeness, per-company/global budgets and current identity rules are unchanged. No social platform crawl, paid search, model call, PDF purchase, login or subscription.\n\n'
    text+='Licences: code MIT; Brreg NLOD 2.0 with attribution; NAV official feed/reuse terms; SSB KLASS CC BY 4.0; company factual excerpts their own terms. Installed dependencies and precise metadata/versions are in installation-final.json: HTTPX/httpcore/respx use BSD licences, tldextract/idna BSD-3-Clause, Pydantic/pytest/urllib3 and several utilities MIT, Requests/requests-file Apache-2.0, certifi MPL-2.0, Pygments BSD-2-Clause, typing_extensions PSF-2.0; others per recorded distribution. Lockfile and dependency metadata are authoritative for exact versions. No LLM models or paid APIs are used. Expected provider cost $0 for both smokes and normal default runs; excludes local compute/storage/network.\n\n'
    text+='Full test/installation/smoke/verification logs, exact argv/config, hash-checked inputs, source manifest, output hashes, dependency licences and request reports are committed. Raw runtime blobs and generated sites remain in the clean clone .data/release-v4b/daily and .data/release-v4b/edge-repeat; no publication occurred. Decisions are recorded in reports/r5/DECISIONS.md. Stop after the local commit/tag; never push.\n'
    (DEST/'RELEASE_REPORT.md').write_text(portable_text(text),encoding='utf8')
    checks={'tested_source_commit':meta['tested_source_commit'],'tested_git_source_tree':source_tree,'release_version':'1.3.0',
        'application_source_unchanged':True,'third_party_dependency_versions_unchanged':True,'all_daily_gates_passed':True,
        'all_edge_gates_passed':True,'daily_http_under_1850':daily['http_requests']<=1850,'daily_wall_under_45_min':daily['wall_seconds']<2700,
        'zero_unsupported_values':True,'all_five_briefing_topics':True,'cost_usd':0,'sample_overlap_zero':True}
    (DEST/'release_checks.json').write_text(portable_text(json.dumps(checks,indent=2)+'\n'),encoding='utf8')
    p=ROOT/'reports/r5/DECISIONS.md';s=p.read_text(encoding='utf-8-sig');s+='\n\n## Release v4b / v1.3.0\n\n- Clean clone of revision/r5 '+meta['tested_source_commit']+'; isolated uv sync --frozen and full pytest before smoke, then again after metadata-only version bump. Source bytes and third-party pins remain unchanged; preserve interpreter/module/lock and licence evidence. No new features or external application code.\n- Draw seed 20261114 uniformly after excluding the prior 200 unique company IDs; zero overlap with both cohorts. Verify the 411160-record universe and snapshot hashes, all 100 valid unique inputs and all extracted rows. Run exactly seven flags with fresh independent states; search/model calls zero.\n- Mock 100: '+str(daily['http_requests'])+' HTTP, '+f"{daily['wall_seconds']:.3f}"+'s wall, '+str(daily['websites'])+' sites, '+str(daily['social_urls'])+' owned social URLs, '+str(daily['jobs'])+' jobs, '+str(daily['facts'])+' facts; 100 ordered terminal envelopes/site and all five topics, zero unsupported values, $0. Edge ten: two invalid checksums/one duplicate preserved, no invalid requests, '+str(edge['http_requests'])+' HTTP, site generated, zero unsupported values. Complete source failures remain explicit.\n- Inventory every published mock website/social/job, with weaker registry assertions separated and exact receipts in release-v4b/urls.md. README reports both prior C samples and the new disjoint mock without claiming causal improvement or an official score. Models/APIs/licences/cost and exact commands are in RELEASE_REPORT.md.\n- Release author/tagger Nethra Venkat; local commit and annotated v1.3.0 only. No push or publication; stop after release.\n';p.write_text(portable_text(s),encoding='utf-8-sig')
    print(json.dumps(checks))

if __name__=='__main__':
    if sys.argv[1]=='version':version()
    else:report()
